css:
.studio {
  font-family: system-ui, -apple-system, "Segoe UI", sans-serif;
  line-height: 1.4;
}
.studio main {
  margin: 0;
  padding: 0.5rem 1rem;
}
.studio .scrud-studio-links {
  display: flex;
  gap: 1rem;
  font-size: 0.875rem;
}
[data-studio-workbench] {
  display: grid;
  gap: 1rem;
}
.studio .studio-workbench {
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
  gap: 0.5rem;
  min-height: 85vh;
}
.studio .studio-topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 1rem;
  border-bottom: 1px solid #d0d0d0;
  padding-bottom: 0.25rem;
}
.studio .studio-title {
  font-size: 1.125rem;
  margin: 0;
}
.studio .studio-badge {
  font-size: 0.75rem;
  font-weight: normal;
  border: 1px solid #888;
  border-radius: 0.25rem;
  padding: 0 0.25rem;
}
.studio .studio-branches {
  margin-right: auto;
  font-size: 0.875rem;
}
.studio .studio-branch-picker-menu {
  position: relative;
}
.studio .studio-branch-picker-summary {
  cursor: pointer;
}
.studio .studio-branch-choices {
  position: absolute;
  z-index: 10;
  min-width: 14rem;
  max-height: 60vh;
  overflow: auto;
  list-style: none;
  margin: 0.25rem 0 0;
  padding: 0.25rem 0.5rem;
  background: #fff;
  border: 1px solid #d0d0d0;
  border-radius: 0.25rem;
}
.studio .studio-branch-choice {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 0.5rem;
  padding: 0.125rem 0;
}
.studio .studio-branch-name {
  color: #555;
}
.studio .studio-branch-choice[data-studio-current] .studio-branch-link,
.studio .studio-branch-choice[data-studio-current] .studio-branch-name {
  font-weight: 600;
}
.studio .studio-toggles {
  display: flex;
  gap: 0.25rem;
}
.studio .studio-toggle[aria-pressed="false"] {
  opacity: 0.6;
}
.studio .studio-notice {
  border: 1px solid #b00020;
  background: #fdecea;
  color: #5f0010;
  padding: 0.25rem 0.5rem;
}
.studio .studio-notice[hidden] {
  display: none;
}
.studio .studio-panes {
  display: flex;
  gap: 0.5rem;
  min-height: 0;
}
.studio .studio-pane {
  flex: 1 1 0;
  min-width: 0;
  overflow: auto;
  border: 1px solid #d0d0d0;
  border-radius: 0.25rem;
  padding: 0.5rem;
}
.studio .studio-pane[data-studio-pane="items"] {
  flex: 0 0 16rem;
}
.studio .studio-pane[data-studio-pane="preview"] {
  flex: 2 1 0;
}
.studio .studio-pane[data-studio-collapsed] {
  flex: 0 0 2rem;
  overflow: hidden;
  padding: 0.5rem 0.25rem;
}
.studio .studio-pane[data-studio-collapsed] > .studio-pane-body {
  display: none;
}
.studio .studio-pane[data-studio-collapsed] > .studio-pane-title {
  writing-mode: vertical-rl;
}
.studio .studio-pane-title {
  font-size: 0.875rem;
  margin: 0 0 0.5rem;
}
.studio .studio-preview {
  width: 100%;
  min-height: 60vh;
  border: 0;
  background: #fff;
}
.studio .studio-items ul {
  list-style: none;
  margin: 0;
  padding: 0;
}
.studio .studio-kind-title {
  font-size: 0.8125rem;
  margin: 0.5rem 0 0.25rem;
}
.studio .studio-item {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.25rem;
  padding: 0.125rem 0 0.125rem 0.25rem;
}
.studio .studio-open {
  background: none;
  border: 0;
  padding: 0;
  font: inherit;
  color: inherit;
  text-align: left;
  cursor: pointer;
}
.studio .studio-own .studio-open {
  font-weight: 600;
}
.studio .studio-packaged .studio-open {
  font-style: italic;
}
.studio .studio-origin,
.studio .studio-applies-to,
.studio .studio-conflict {
  font-size: 0.75rem;
  color: #555;
}
.studio .studio-conflict-parent,
.studio .studio-conflict-layer {
  border-left: 3px solid #b00020;
}
.studio .studio-conflict {
  color: #b00020;
}
.studio .studio-override {
  font-size: 0.75rem;
}
.studio .studio-strip {
  border-top: 1px solid #d0d0d0;
  padding-top: 0.25rem;
  font-size: 0.875rem;
}
.studio .studio-status {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 1rem;
}
.studio .studio-chain {
  display: flex;
  gap: 0.5rem;
  list-style: none;
  margin: 0;
  padding: 0;
}
.studio .studio-chain-published {
  font-style: italic;
}
.studio .studio-count-conflicts {
  color: #b00020;
}
.studio .studio-actions {
  display: flex;
  gap: 0.5rem;
}
.studio .studio-promotes {
  flex-basis: 100%;
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}
.studio .studio-promote-panel {
  border: 1px solid #d0d0d0;
  border-radius: 4px;
  margin: 0.25rem 0;
  padding: 0.5rem;
  max-height: 50vh;
  overflow: auto;
}
.studio .studio-promote-panel[hidden],
.studio .studio-promote-reason[hidden],
.studio .studio-promote-note[hidden] {
  display: none;
}
.studio .studio-promote-reason {
  color: #b00020;
}
.studio .studio-promote-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
}
.studio .studio-pushes {
  flex-basis: 100%;
}
.studio .studio-push-list {
  margin: 0.25rem 0;
  padding-left: 1.25rem;
}
.studio .studio-push-state {
  font-size: 0.75rem;
  color: #555;
}
.studio .studio-push-unreadable,
.studio .studio-push-conflicts {
  color: #b00020;
}
.studio .studio-push-changes {
  padding-left: 1.25rem;
}
.studio .studio-push-sides {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr));
  gap: 0.5rem;
}
.studio .studio-push-fields {
  margin: 0;
}
.studio .studio-push-field {
  display: grid;
  grid-template-columns: 8rem minmax(0, 1fr);
  gap: 0.5rem;
}
.studio .studio-push-field dd {
  margin: 0;
  min-width: 0;
}
.studio .studio-push-field pre {
  margin: 0;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}
.studio .studio-push-field-changed {
  background: #fff6d5;
}
.studio .studio-push-record div {
  display: flex;
  gap: 0.5rem;
}
.studio .studio-push-record dt {
  min-width: 6rem;
  font-weight: 600;
}
.studio .studio-push-record dd {
  margin: 0;
}
.studio .studio-push-state-form {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem;
  margin: 0.5rem 0;
}
.studio [data-studio-push-after] {
  margin: 1rem 0;
}
.studio [data-studio-push-after-controls] {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem;
  margin: 0.5rem 0;
}
.studio .studio-pane[data-studio-collapsed] > .studio-editor-head,
.studio .studio-pane[data-studio-collapsed] > .studio-draft-errors {
  display: none;
}
.studio .studio-editor-head {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.5rem;
  margin-bottom: 0.5rem;
}
.studio .studio-editor-head[hidden],
.studio .studio-draft-errors[hidden] {
  display: none;
}
.studio .studio-editor-title {
  font-size: 1rem;
  margin: 0;
}
.studio .studio-editor-origin,
.studio .studio-editor-meta {
  font-size: 0.75rem;
  color: #555;
}
.studio .studio-editor-meta {
  margin: 0 0 0.25rem;
}
.studio .studio-code {
  display: block;
  box-sizing: border-box;
  width: 100%;
  min-height: 20rem;
  margin: 0;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.8125rem;
  line-height: 1.45;
  tab-size: 2;
  white-space: pre;
  overflow: auto;
}
.studio .studio-code[readonly],
.studio pre.studio-code {
  background: #f6f6f6;
}
.studio .studio-code-label {
  display: block;
  font-size: 0.75rem;
  margin-bottom: 0.25rem;
}
.studio .studio-note {
  font-size: 0.8125rem;
  border-left: 3px solid #888;
  padding-left: 0.5rem;
}
.studio .studio-editor-actions,
.studio .studio-editor + .studio-revert,
.studio .studio-editor + .studio-delete {
  margin-top: 0.5rem;
}
.studio .studio-revert,
.studio .studio-delete {
  font-size: 0.8125rem;
}
.studio .studio-draft-errors {
  margin-top: 0.5rem;
  border: 1px solid #b00020;
  padding: 0.25rem 0.5rem;
  font-size: 0.8125rem;
  color: #5f0010;
}
.studio .studio-draft-errors p,
.studio .studio-draft-errors ul {
  margin: 0;
}
.studio .studio-stylesheet .studio-sheet-name {
  margin: 0 0 0.5rem;
}
.studio .studio-sheet-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 0.25rem 1rem;
  margin: 0 0 0.5rem;
}
.studio dl.studio-sheet-fields dt,
.studio dl.studio-prefixes dt {
  font-size: 0.75rem;
  color: #555;
}
.studio dl.studio-sheet-fields dd,
.studio dl.studio-prefixes dd {
  margin: 0 0.75rem 0 0;
}
.studio dl.studio-prefixes {
  display: grid;
  grid-template-columns: max-content 1fr;
  gap: 0.125rem 0.5rem;
  margin: 0 0 0.5rem;
}
.studio .studio-field {
  display: inline-flex;
  flex-direction: column;
  gap: 0.125rem;
}
.studio .studio-field-label,
.studio .studio-rule-append label {
  font-size: 0.75rem;
  color: #555;
}
.studio .studio-field-input {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-size: 0.8125rem;
  min-width: 10rem;
}
.studio .studio-field-input[aria-invalid="true"] {
  border-color: #b00020;
}
.studio .studio-field-errors {
  margin: 0;
  padding-left: 1rem;
  font-size: 0.75rem;
  color: #5f0010;
}
.studio .studio-prefixes {
  border: 1px solid #ddd;
  margin: 0 0 0.5rem;
  padding: 0.25rem 0.5rem;
}
.studio .studio-prefix {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  margin: 0.125rem 0;
}
.studio .studio-prefix-key {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  min-width: 4rem;
}
.studio .studio-rules-title {
  font-size: 0.875rem;
  margin: 0.5rem 0 0.25rem;
}
.studio .studio-rule-list {
  margin: 0;
  padding-left: 1.5rem;
}
.studio .studio-rule {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.5rem;
  padding: 0.25rem;
  border-radius: 3px;
}
.studio .studio-rule:focus-within,
.studio .studio-rule:focus {
  background: #eef4ff;
  outline: 1px solid #5b8def;
}
.studio .studio-rule-row {
  display: inline-flex;
  flex-wrap: wrap;
  align-items: flex-end;
  gap: 0.5rem;
}
.studio .studio-rule-arrow {
  padding-bottom: 0.125rem;
}
.studio .studio-rule-ops {
  display: inline-flex;
  gap: 0.25rem;
  font-size: 0.75rem;
}
.studio .studio-rule-counts {
  margin: 0.25rem 0;
  font-size: 0.8125rem;
}
.studio .studio-rule-counts[hidden] {
  display: none;
}
.studio .studio-rule-append {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem 0.5rem;
  margin-top: 0.5rem;
}
.studio .studio-hint {
  color: #555;
  font-size: 0.8125rem;
}
.studio .studio-preview-controls {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.25rem 0.75rem;
  margin-bottom: 0.5rem;
  font-size: 0.8125rem;
}
.studio .studio-types .scrud-resource {
  display: inline;
}
.studio .studio-control {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
}
.studio .studio-control input[type="text"] {
  width: 8rem;
}
.studio .studio-inspector {
  border-top: 1px solid #d0d0d0;
  margin-top: 0.5rem;
  padding-top: 0.25rem;
  font-size: 0.8125rem;
}
.studio .studio-inspector-title {
  font-size: 0.875rem;
  margin: 0 0 0.25rem;
}
.studio .studio-inspector-node,
.studio .studio-facts dd {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  overflow-wrap: anywhere;
}
.studio .studio-facts {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 0.125rem 0.5rem;
  margin: 0.25rem 0;
}
.studio .studio-facts dd {
  margin: 0;
}
.studio .studio-explain-rules {
  margin: 0.25rem 0;
  padding-left: 1.5rem;
  overflow-wrap: anywhere;
}
.studio .studio-inspector-actions {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 0.5rem;
  margin: 0.25rem 0;
}
.studio .studio-new-rule {
  display: grid;
  gap: 0.25rem;
  border: 1px solid #ddd;
  padding: 0.5rem;
  margin-top: 0.25rem;
}
.studio .studio-new-rule[hidden] {
  display: none;
}
.studio .studio-new-rule-title {
  font-size: 0.875rem;
  margin: 0;
}
.studio .studio-new-rule textarea {
  width: 100%;
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
}
.studio .studio-new-rule-create {
  justify-self: start;
}
.studio .studio-result {
  margin: 0;
}
.studio .studio-branch-tools {
  display: flex;
  flex-wrap: wrap;
  align-items: flex-start;
  gap: 0.5rem 1rem;
  font-size: 0.8125rem;
}
.studio .studio-branch-panel,
.studio .studio-new-branch-panel {
  border: 1px solid #d0d0d0;
  border-radius: 0.25rem;
  padding: 0.125rem 0.5rem;
}
.studio .studio-branch-summary {
  cursor: pointer;
}
.studio .studio-branch-settings,
.studio .studio-new-branch {
  display: grid;
  gap: 0.5rem;
  padding: 0.25rem 0;
}
.studio .studio-branch-facts,
.studio .studio-version-record {
  margin: 0;
}
.studio .studio-branch-facts div,
.studio .studio-version-record div {
  display: flex;
  gap: 0.5rem;
}
.studio .studio-branch-facts dt,
.studio .studio-version-record dt {
  color: #555;
  min-width: 6rem;
}
.studio .studio-branch-facts dd,
.studio .studio-version-record dd {
  margin: 0;
  overflow-wrap: anywhere;
}
.studio .studio-branch-description {
  white-space: pre-wrap;
}
.studio .studio-branch-fields {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1rem;
}
.studio .studio-field-wide {
  flex: 1 1 20rem;
}
.studio .studio-field-wide textarea {
  width: 100%;
}
.studio .studio-field-prefix {
  display: flex;
  flex-wrap: wrap;
  align-items: baseline;
  gap: 0.25rem 0.5rem;
}
.studio .studio-branch-actions {
  display: flex;
  gap: 0.5rem;
}
.studio .studio-new-branch {
  grid-template-columns: repeat(auto-fill, minmax(10rem, 1fr));
  align-items: end;
}
.studio .studio-created {
  margin: 0.25rem 0;
}
.studio .studio-versions {
  font-size: 0.8125rem;
}
.studio .studio-version-list {
  margin: 0.25rem 0;
  padding-left: 1.5rem;
}
.studio .studio-version-title {
  font-size: 1.125rem;
}
.studio .studio-version-kind-title {
  font-size: 0.9375rem;
  margin: 0.75rem 0 0.25rem;
}
.studio .studio-version-items {
  margin: 0;
  padding-left: 1.25rem;
}
.studio .studio-version-item {
  margin: 0.25rem 0;
}
.studio .studio-version-name {
  font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  font-weight: 600;
}
.studio .studio-version-applies,
.studio .studio-version-marker {
  color: #555;
}
.studio .studio-version-deleted .studio-version-name {
  text-decoration: line-through;
}
.studio .studio-version-code {
  margin: 0.25rem 0;
  padding: 0.25rem 0.5rem;
  background: #f6f6f6;
  border: 1px solid #e0e0e0;
  overflow: auto;
  max-height: 16rem;
  font-size: 0.8125rem;
}
.studio .studio-version-entry .studio-restore {
  margin-left: 0.5rem;
  font-size: 0.75rem;
}
